// Generated by `hct contract generate` from the toolkit contract definitions. Do not edit.
//
// Contract "1": the page data a format-1 template is rendered with. Frozen:
// nothing here is ever renamed, retyped or removed.

export const CONTRACT_VERSION = '1'

/**
 * StoreBusinessInfo is the business details a store publishes, for footers and
 * legal pages. Any of them may be empty.
 */
export interface StoreBusinessInfo {
  address_line1: string
  address_line2: string
  city: string
  state: string
  country: string
  postal_code: string
  business_number: string
  /** The VAT or GST registration number. */
  tax_number: string
  phone_number: string
  billing_email: string
}

/**
 * StoreTheme is the palette the store has chosen. Every value is a hex colour,
 * and every colour is always set: a store that never chose one gets the
 * platform default.
 */
export interface StoreTheme {
  /** The page. */
  background: string
  /** Cards on the page. */
  surface: string
  /** Inputs and controls on those cards. */
  surface_raised: string
  border: string
  text: string
  text_muted: string
  /** The first stop of the brand gradient. */
  accent: string
  /** The second stop of the brand gradient. */
  accent_strong: string
}

/**
 * StorePublicInfo is the store a page belongs to. Any URL may be empty when
 * the store has not set it.
 */
export interface StorePublicInfo {
  store_name: string
  website_domain: string
  logo_url: string
  favicon_url: string
  terms_of_service_url: string
  privacy_policy_url: string
  root_redirect_url: string
  /**
   * Artwork beside the login and forgot-password forms. Empty means the
   * platform image.
   */
  login_image_url: string
  /** Artwork above the signup form. Empty means the platform image. */
  signup_image_url: string
  business_info: StoreBusinessInfo
  theme: StoreTheme
}

/** MarketingFeature is one bullet of store-written marketing copy. */
export interface MarketingFeature {
  icon: string
  text: string
}

/** Marketing is store-authored copy attached to a group or service. */
export interface Marketing {
  title: string
  description: string
  /** Never null; empty when the store wrote none. */
  features: MarketingFeature[]
}

/**
 * ServiceGroup is a group of services, as the navigation and catalogue pages
 * list it.
 */
export interface ServiceGroup {
  id: string
  name: string
  slug: string
  description: string
  /** An image URL, or empty. */
  image: string
  marketing: Marketing
}

/**
 * ServiceType is what kind of product a service is. Templates use it to pick a
 * layout: a game-server catalogue and a web-hosting price table are different
 * pages. It is the empty string for a service whose store has not set a type.
 */
export type ServiceType = 'game-server' | 'web-hosting' | 'dedicated-server' | 'vps' | 'other' | ''

export const ServiceTypeValues = ['game-server', 'web-hosting', 'dedicated-server', 'vps', 'other', ''] as const

/** Service is one product a store sells, with its plans listed separately. */
export interface Service {
  id: string
  group_id: string
  name: string
  slug: string
  /** The service's marketing description. */
  description: string
  /** An image URL, or empty. */
  image: string
  type: ServiceType
  marketing: Marketing
  /**
   * True when the service has exactly one orderable plan. Link it straight to
   * /checkout/{slug} instead of /{group}/{slug}; the rendering engine
   * redirects its service page there anyway.
   */
  single_plan: boolean
}

/**
 * PriceInterval is a plan's billing cycle. A plan leads with the shortest
 * cycle it has enabled.
 */
export type PriceInterval = 'month' | 'quarter' | 'semi_annual' | 'year'

export const PriceIntervalValues = ['month', 'quarter', 'semi_annual', 'year'] as const

/** Price is a price normalised for display. */
export interface Price {
  /** Major units, ready to render. */
  amount: number
  /** An ISO 4217 code. */
  currency: string
  interval: PriceInterval
}

/** ServicePlanPricing is the price a plan leads with. */
export interface ServicePlanPricing {
  price: Price
  /** A struck-through earlier price. Absent when there is none. */
  original_price?: Price
}

/** PaymentType is how a plan is paid for. */
export type PaymentType = 'free' | 'free_trial' | 'recurring'

export const PaymentTypeValues = ['free', 'free_trial', 'recurring'] as const

/** OrderFormComponentType is the kind of input an order form component renders. */
export type OrderFormComponentType = 'string' | 'checkbox' | 'radio' | 'slider' | 'dropdown' | 'location-multi-dropdown'

export const OrderFormComponentTypeValues = ['string', 'checkbox', 'radio', 'slider', 'dropdown', 'location-multi-dropdown'] as const

/**
 * OrderFormOption is one choice on a radio, slider or dropdown component, or
 * inside a location region.
 */
export interface OrderFormOption {
  label: string
  value: string
  /** An add-on price in minor units (cents). */
  price: number
}

/**
 * OrderFormRegion is a top-level group inside a location-multi-dropdown, such
 * as a country holding its cities.
 */
export interface OrderFormRegion {
  order: number
  label: string
  default: boolean
  default_value: string
  /** May be null. */
  children: OrderFormOption[] | null
}

/**
 * OrderFormComponent is one field a customer fills in when ordering a plan.
 * Only the keys relevant to its type are present.
 */
export interface OrderFormComponent {
  order: number
  type: OrderFormComponentType
  label: string
  description: string
  /** The name the answer is recorded under. */
  key: string
  required: boolean
  /** Set on string components. */
  placeholder?: string
  /** Set on string components. */
  regex?: string
  /** Set on checkbox components. */
  default_value?: boolean
  /** Set on checkbox components: an add-on price in minor units (cents). */
  price?: number
  /** Set on radio, slider and dropdown components. */
  children?: OrderFormOption[]
  /** Set on location-multi-dropdown components. */
  dropdown?: OrderFormRegion[]
  /** Set when the component is a copy of a store-wide preset. */
  preset_id?: string
}

/** ServiceOrderFormRow is one component of a plan's order form. */
export type ServiceOrderFormRow = OrderFormComponent

/** ServicePlan is one way to buy a service. */
export interface ServicePlan {
  id: string
  service_id: string
  name: string
  slug: string
  description: string
  /** An image URL, or empty. */
  image: string
  pricing: ServicePlanPricing
  /** Days of free trial. Zero unless payment_type is free_trial. */
  trial_days: number
  payment_type: PaymentType
  /**
   * How an order is fulfilled: "module" (automatically) or "manual" (by the
   * store's staff).
   */
  provisioning: string
  /** May be null when the plan has no order form. */
  order_form: ServiceOrderFormRow[] | null
}

/** Cta is a call-to-action link. */
export interface Cta {
  label: string
  href: string
}

/** HeroContent is the copy at the top of the home page. */
export interface HeroContent {
  title: string
  subtitle: string
  highlights: string[]
  primary_cta: Cta
  secondary_cta: Cta
}

/** Section is the heading pair above a block of content. */
export interface Section {
  title: string
  subtitle: string
}

/** FeatureCard is one card in the features block. */
export interface FeatureCard {
  title: string
  description: string
}

/** FeaturesContent is the features block. */
export interface FeaturesContent extends Section {
  cards: FeatureCard[]
}

/** FaqEntry is one question and its answer. */
export interface FaqEntry {
  question: string
  answer: string
}

/** FaqContent is the FAQ block. */
export interface FaqContent extends Section {
  items: FaqEntry[]
}

/**
 * StoreContent is the copy a store edits in its admin panel. It is on every
 * page, so a template can render the section headings and FAQ wherever it
 * likes.
 */
export interface StoreContent {
  hero: HeroContent
  categories: Section
  features: FeaturesContent
  faq: FaqContent
}

/**
 * DomainTLD is one extension on the domain pricing table. Prices are for one
 * year in major units; zero means the store does not offer that operation.
 */
export interface DomainTLD {
  tld: string
  featured: boolean
  register: number
  transfer: number
  renew: number
}

/** PageType is which page a payload is for. */
export type PageType = 'home' | 'group' | 'service' | 'domains' | 'not-found'

export const PageTypeValues = ['home', 'group', 'service', 'domains', 'not-found'] as const

/** PageMeta is what goes in the document head. */
export interface PageMeta {
  title: string
  description: string
  /** Absent when empty. */
  og_image?: string
  /** Absent unless true. */
  no_index?: boolean
}

/**
 * BasePageData is what every page carries: a layout renders the store and its
 * navigation on every route.
 */
export interface BasePageData {
  page_type: PageType
  meta: PageMeta
  store: StorePublicInfo
  /** The store's enabled groups, in display order. Never null. */
  service_groups: ServiceGroup[]
  content: StoreContent
  /**
   * Whether the store sells domains. On every page because the navigation is,
   * so a template never links to a domains page that would 404.
   */
  domains_enabled: boolean
}

/** HomePageData is the payload for "/". */
export interface HomePageData extends BasePageData {
  page_type: 'home'
}

/**
 * GroupPageServiceEntry pairs a service with the cheapest plan a visitor could
 * buy it on, which is what a catalogue tile shows.
 */
export interface GroupPageServiceEntry {
  service: Service
  /**
   * The lowest price compared per month, so a yearly plan does not win by
   * being billed less often.
   */
  cheapest_plan: ServicePlan
}

/** GroupPageData is the payload for "/{group}". */
export interface GroupPageData extends BasePageData {
  page_type: 'group'
  group: ServiceGroup
  /** Services with at least one orderable plan. Never null. */
  services: GroupPageServiceEntry[]
}

/** ServicePageData is the payload for "/{group}/{service}". */
export interface ServicePageData extends BasePageData {
  page_type: 'service'
  service: Service
  /** Every orderable plan. Never null. */
  plans: ServicePlan[]
}

/**
 * DomainsPageData is the payload for "/domains". It exists only when the store
 * sells domains.
 */
export interface DomainsPageData extends BasePageData {
  page_type: 'domains'
  /**
   * Empty when the store sells domains but has added no extensions. Never
   * null.
   */
  tlds: DomainTLD[]
  /** An ISO 4217 code. */
  currency: string
}

/** NotFoundPageData is the payload for a path no page matches. */
export interface NotFoundPageData extends BasePageData {
  page_type: 'not-found'
}

/** PageData is any page payload, told apart by page_type. */
export type PageData = HomePageData | GroupPageData | ServicePageData | DomainsPageData | NotFoundPageData

/** PageDataMap maps each page id to the type of its data. */
export interface PageDataMap {
  home: HomePageData
  'catalog.group': GroupPageData
  'catalog.service': ServicePageData
  domains: DomainsPageData
  'not-found': NotFoundPageData
}

/** ContractPageId is a page that carries data in this contract. */
export type ContractPageId = keyof PageDataMap
